<template><div class="vital-layer" @mousedown.self="$emit('close')"><section class="vital-modal" role="dialog" aria-modal="true"><header><div class="title"><span><i class="ph ph-heartbeat"></i></span><div><small>RESUMEN CLÍNICO</small><h2>Signos vitales</h2><p>{{ patient.nombre }} · {{ patient.identificacion }}</p></div></div><button class="btn-close" @click="$emit('close')"></button></header><div class="modal-body"><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="error" class="alert alert-danger">{{ error }} <button class="btn btn-sm btn-outline-danger ms-2" @click="load">Reintentar</button></div><template v-else><div v-if="latest?.tiene_alertas" class="alert alert-danger"><i class="ph ph-warning me-2"></i><strong>Los últimos signos vitales presentan alertas clínicas.</strong></div><div v-if="latest" class="vitals"><div><i class="ph ph-wave-sine"></i><small>Presión arterial</small><strong>{{ latest.presion_arterial?.texto || `${latest.sv_pa_sistolica || '—'}/${latest.sv_pa_diastolica || '—'}` }}</strong></div><div><i class="ph ph-heart"></i><small>Frecuencia cardiaca</small><strong>{{ latest.frecuencia_cardiaca ?? '—' }} <em>lpm</em></strong></div><div><i class="ph ph-wind"></i><small>Frecuencia respiratoria</small><strong>{{ latest.frecuencia_respiratoria ?? '—' }} <em>rpm</em></strong></div><div><i class="ph ph-thermometer"></i><small>Temperatura</small><strong>{{ latest.temperatura ?? '—' }} <em>°C</em></strong></div><div><i class="ph ph-drop"></i><small>Saturación</small><strong>{{ latest.saturacion_oxigeno ?? latest.saturacion ?? '—' }} <em>%</em></strong></div><div><i class="ph ph-clock"></i><small>Última toma</small><strong class="date">{{ formatDate(latest.fecha_hora_toma || latest.fecha_actividad) }}</strong></div></div><div v-else class="empty"><i class="ph ph-heartbeat"></i><h3>Sin signos vitales registrados</h3><p>No se encontraron tomas recientes para este paciente.</p></div></template></div><footer><span>{{ total }} registros recientes</span><button class="btn btn-outline-secondary" @click="$emit('close')">Cerrar</button></footer></section></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{obtenerMensajeError}from'@/services/api';import{consultarUltimosSignosVitales}from'@/services/hospitalizacion';const props=defineProps({patient:Object});defineEmits(['close']);const data=ref(null),loading=ref(true),error=ref('');const rows=computed(()=>Array.isArray(data.value)?data.value:data.value?.data||data.value?.registros||[]);const latest=computed(()=>data.value?.ultimo||rows.value[0]||props.patient?.signos_vitales?.ultimo||null);const total=computed(()=>data.value?.total_registros??rows.value.length??props.patient?.signos_vitales?.total_registros??0);const formatDate=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(v).replace(' ','T'))):'No informada';async function load(){loading.value=true;error.value='';try{data.value=await consultarUltimosSignosVitales(props.patient.id_paciente)}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.vital-layer{position:fixed;inset:0;z-index:1080;display:grid;place-items:center;padding:1rem;background:rgba(6,19,33,.65);backdrop-filter:blur(5px)}.vital-modal{width:min(720px,100%);max-height:94vh;overflow:auto;border-radius:1rem;background:#fff;box-shadow:0 30px 90px rgba(0,0,0,.3)}.vital-modal>header,.vital-modal>footer{display:flex;justify-content:space-between;align-items:center;padding:1rem 1.25rem;border-bottom:1px solid #e5ebf0}.vital-modal>footer{border-top:1px solid #e5ebf0;border-bottom:0}.title{display:flex;gap:.7rem}.title>span{display:grid;place-items:center;width:44px;height:44px;border-radius:13px;background:#ffebee;color:#d34452;font-size:1.3rem}.title small{color:#d34452;font-size:.6rem;font-weight:800}.title h2{font-size:1.1rem;margin:.1rem 0}.title p{margin:0;color:#718096;font-size:.7rem}.modal-body{padding:1.25rem}.vitals{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem}.vitals>div{position:relative;padding:.9rem;border:1px solid #e3eaf0;border-radius:.75rem}.vitals>div>i{color:var(--bs-primary);font-size:1.2rem}.vitals small,.vitals strong{display:block}.vitals small{margin-top:.4rem;color:#7b899a;font-size:.63rem}.vitals strong{font-size:1rem}.vitals em{color:#8491a1;font-size:.6rem;font-style:normal}.vitals .date{font-size:.72rem}.empty{text-align:center;padding:2.5rem;color:#718096}.empty i{font-size:2.8rem;color:#aec1d0}.empty h3{font-size:1.05rem}.vital-modal>footer span{color:#718096;font-size:.7rem}@media(max-width:600px){.vitals{grid-template-columns:1fr 1fr}}</style>
